EXCLUDE=re.compile(r'\b(?:еър фрайър|лампа|фенер|тонколон|сешоар|юти[яи]|парфюм|плюш|конструкт|кукл|пистолет|автомат|чехли|джапанк|ваза|солнич|солник|ренде|белачк|джезве|точилк|шпатула|черпак|термос|бутилк|буркан|пепелник|запалк|химикал|тетрис|четка за коса|сапунерк|шнол|гъба за грим|слънчеви очил|плаж.*топк|щипки за пране|щипки за коса|кухненски чук|чук кухненски)')
def normalize(text):
 s=html.unescape(str(text)).lower()
 s=re.sub(r'(?<![a-zа-я])([a-z])(?=[а-я])',lambda m:{'a':'а','k':'к','m':'м','o':'о','p':'р','t':'т','x':'х'}.get(m[1],m[1]),s)
 return s.replace('aлбум','албум')
def classify(product,allowed,overrides=None):
 if overrides and str(product['id']) in overrides:
  cat=int(overrides[str(product['id'])]['category_id']);return (cat,'override') if cat in allowed else (None,'override_category_not_in_template')
 s=normalize(product.get('name',''))
 # Display carton text can mention unrelated objects; it is not the product type.
 display=re.search(r'\bв (?:кутия|кутии|стек|кашон)\b',s)
 if display and display.start()>10:s=s[:display.start()]
 s=re.sub(r'\b(?:самоизточващ се )?микрофибърен моп', 'моп',s)
 candidates=[]
 for i,(cat,pattern) in enumerate(COMPILED):
  if cat not in allowed:continue
  for m in pattern.finditer(s):
   if m.start() and s[m.start()-1].isalpha():continue
   candidates.append((m.start(),i,cat));break
 if not candidates:return None,'no_supported_product_type'
 first=min(candidates);excluded=EXCLUDE.search(s)
 unsupported=re.search(r'\b(?:кофа|кофи|леген|чаршаф.*плик|гъба.*пудра|четка.*зъб|листовка|нудълс|тапа за мивка|подложка за топло|поставка за телефон|играчка|магнит|фризби|спинер|тетрадка|дрънкалка|хвърчило|часовник|термометър|помпа|калъф за очила|шише|саксия|солница|кана|фуния|резачка за зеленчуци|колан.*(?:гръбнак|куфар|куфер)|кутия.*(?:цигар|торта|за клечки|за тампони)|цедка.*чай|органайзер.*гардероб)',s)
 if unsupported and unsupported.start()<=first[0]:return None,'unsupported_main_product_type'
 disallowed=re.search(r'\b(?:колан.*(?:кръст|крачол)|калъф.*куфар|магическ.*дъска|дъска.*рисув|подложка.*чаш|кантар|закачалка|ластици.*(?:кос|цвете)|ключодържател|албум.*(?:покемон|покемн|карти)|куки.*стелаж|снадка.*маркуч|ножкорез|парти.*шапк|шапк.*(?:парти|хаги|детск|малборо)|мъжки коледни чорап|дамски коледни чорап)',s)
 if disallowed and disallowed.start()<=first[0]:return None,'unsupported_accessory_or_product_type'
 if excluded and excluded.start()<=first[0]:return None,'unsupported_main_product_type'
 cat=first[2]
 if re.search(r'(?:^|\s)(?:дамско бельо|куфар за инструменти|стол раница|детски коледни чорапи|поставка.*лъжиц|лъжиц.*постав)',s):return None,'unsupported_accessory_or_product_type'
 if cat==1313 and 'молив' in s:return None,'pencils_are_not_geometry_set'
 if cat==9752 and not re.search(r'cake pop|кейк.?поп|попс',s):return None,'cake_pop_molds_do_not_include_cookie_cutters'
 if cat in {5436,54156} and any(word in s for word in ['за хладилник']):return None,'container_is_not_utility_rack'
 if cat==34864 and any(c['id'] in {411,412,446} for c in product.get('categories',[])):return None,'party_toy_or_christmas_hat'
 if cat==9995 and 'цедка' in s and 'гевгир' not in s:return None,'strainer_is_not_colander'
 if cat==13001 and (re.search(r'светещ|батери|led|украса.*елх',s) or not re.search(r'^(?:изкуствена |коледна )?елха\b',s.strip())):return None,'tree_shaped_ornament_is_not_christmas_tree'
 # These words must identify a real product, not its retail/display packaging.
 if cat==54156 and re.search(r'\b(?:в кутия|в кути[ий]|размер опаков)',s[:first[0]+6]):return None,'packaging_not_storage_box'
 return cat,'product_type'
